"""Flash-attention dispatch: cubin launchers + AOT forward wrapper.

One entry per kernel class. `launch_forward` resolves the AOT-emitted
host wrapper (which bakes TMA desc construction, cluster config, etc.)
and calls its `ciface` entry. The other `launch_*` variants dispatch
directly through the cubin runtime.

None-valued compile-time args (e.g. `window_size_left=None`) get folded
out by `cute.compile` into compile-time constants, so the cubin/wrapper
runtime ABI excludes them. Callers only pass what's present.

When `KESTREL_CUTE_JIT=1`, missing variants are compiled on demand via
`cubin_bundles.jit_compile_and_install` (cubin families) or
`AotFamily`'s built-in JIT path (forward). Source install only. JIT is STRICT:
a compile failure raises rather than silently falling back to torch SDPA.
"""


import ctypes
import math

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.cute_aot_runtime import get_raw_stream, AotFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled
from kestrel_kernels.arch import get_cuda_arch
from kestrel_kernels.flash_attn.cute.variant import (
    FlashAttnVariant,
    FlashAttnSm80ForwardVariant,
    FlashAttnDecodePersistentSplitFusedVariant,
)


_family = CubinFamily("flash_attn")

_ENABLE_JIT = is_cute_jit_enabled()
if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles
    from scripts.precompile.cubin_bundles import (
        _compile_flash_attn_forward,
        _compile_flash_attn_decode_sm90,
        _compile_flash_attn_sm80_forward,
        _compile_flash_attn_persistent_split_fused,
    )
else:
    _cubin_bundles = None
    _compile_flash_attn_forward = None
    _compile_flash_attn_decode_sm90 = None
    _compile_flash_attn_sm80_forward = None
    _compile_flash_attn_persistent_split_fused = None


_aot_forward = AotFamily(
    "flash_attn",
    jit_compile_fn=_compile_flash_attn_forward if _ENABLE_JIT else None,
)

# SM80 forward also routes through the AOT host wrapper (not the raw-cubin
# CubinFamily launcher). The cute-generated wrapper invokes the device kernel in
# its own compile-determined param order, so it is immune to that order — which
# the direct-launch path reconstructs from c_header and gets wrong for
# aux-bearing (block_bidirectional) variants, where the kernel's internal param
# ordering is non-deterministic (PYTHONHASHSEED-dependent).
_aot_sm80_forward = AotFamily(
    "flash_attn",
    jit_compile_fn=_compile_flash_attn_sm80_forward if _ENABLE_JIT else None,
)

_M_BLOCK = 128  # matches interface_sm90 default for all shipped variants


def _decode_group_count(variant: FlashAttnVariant) -> int:
    """Match FlashAttentionDecodeSm90's grouped-query block decomposition."""
    assert variant.kind == "decode_sm90"
    qhead_per_kvhead = int(variant.qhead_per_kvhead)
    if qhead_per_kvhead == 1:
        return 1

    dtype_kv_name = variant.dtype_kv_name or variant.dtype_name
    vec_size = 16 if dtype_kv_name == "fp8_e4m3" else 8
    bdx = int(variant.head_dim) // vec_size
    max_qheads_per_block = 8
    warp_size = 32

    bdy_nominal = min(qhead_per_kvhead, max_qheads_per_block)
    bdy_min = (warp_size + bdx - 1) // bdx
    warp_multiple = warp_size // math.gcd(warp_size, bdx)
    bdy = max(bdy_nominal, bdy_min)
    bdy = ((bdy + warp_multiple - 1) // warp_multiple) * warp_multiple
    if bdy > max_qheads_per_block:
        bdy = (max_qheads_per_block // warp_multiple) * warp_multiple
        if bdy < bdy_min:
            bdy = bdy_min
    return (qhead_per_kvhead + bdy - 1) // bdy


def _ensure_available(variant_key: str, first_tensor: torch.Tensor,
                      jit_compile_fn_factory, variant_for_jit,
                      block_x: int, *, require_packed: bool = False) -> bool:
    """Ensure the cubin family has `variant_key` ready to launch.

    Returns True if the variant is usable (either shipped in the bundle
    for this arch, already JIT-installed for this device, or just
    JIT-compiled on demand). Returns False if not shipped and either
    JIT is disabled or JIT compilation fails — callers should fall back
    to torch in that case.
    """
    if _family.is_available(variant_key):
        return True
    if require_packed:
        return False
    device_index = int(first_tensor.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    try:
        _cubin_bundles.jit_compile_and_install(
            family=_family,
            variant_key=variant_key,
            compile_fn=jit_compile_fn_factory(variant_for_jit),
            block_x=block_x,
            device_index=device_index,
        )
    except Exception as exc:
        # KESTREL_CUTE_JIT=1 is strict: a JIT compile failure raises rather than
        # silently degrading to a slow torch SDPA fallback that hides the error.
        raise RuntimeError(
            f"[kestrel-kernels] JIT compile failed for {variant_key} "
            "(KESTREL_CUTE_JIT=1 is a development path; use a wheel that "
            "includes this precompiled variant, or unset KESTREL_CUTE_JIT)."
        ) from exc
    return True


# The cute DSL kernel ABI puts all tensor structs first, then scalars,
# regardless of the __call__ wrapper's argument ordering. `launch_*`
# functions below pass args in that tensors-then-scalars order, matching
# how `_build_param_signature` emits the manifest's `param_signature`.


# ---------------------------------------------------------------------------
# launch_forward — FlashAttentionForwardSm90 / FlashAttentionForwardSm100
#
# Forward needs the cute-emitted host wrapper (TMA descriptors + scheduler
# Params). We ship an AOT `.so` per (variant, arch). See
# docs/CUTE_RUNTIME_REFACTOR_DESIGN.md § "Flash Attention Host Wrapper: AOT Path".
# ---------------------------------------------------------------------------

def launch_forward(
    variant: FlashAttnVariant,
    q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, out: torch.Tensor,
    softmax_scale: float, k_scale: float, v_scale: float,
    cu_seqlens_q: torch.Tensor | None,
    cu_seqlens_k: torch.Tensor | None,
    seqused_q: torch.Tensor | None,
    seqused_k: torch.Tensor | None,
    page_table: torch.Tensor | None,
    *,
    batch_size: int, seqlen_q: int | None, num_heads_kv: int,
    qhead_per_kvhead: int, pack_gqa: bool, sm_count: int,
    aux_tensors: "list | None" = None,
    window_size_left: int | None = None,
    window_size_right: int | None = None,
    require_packed: bool = False,
) -> bool:
    assert variant.kind in ("forward_sm90", "forward_sm100")
    if variant.local and (window_size_left is None or window_size_right is None):
        raise ValueError("local forward variants require both window bounds")
    if not variant.local and (
        window_size_left is not None or window_size_right is not None
    ):
        raise ValueError("non-local forward variants cannot receive window bounds")

    resolver = (
        _aot_forward.resolve_shipped if require_packed else _aot_forward.resolve
    )
    bundle = resolver(variant, get_cuda_arch())
    if bundle is None:
        del batch_size, seqlen_q, num_heads_kv, qhead_per_kvhead, pack_gqa, sm_count
        del cu_seqlens_q, cu_seqlens_k, seqused_q, seqused_k, page_table
        del softmax_scale, k_scale, v_scale, aux_tensors
        del k, v, out
        return False

    bundle.aot._ensure_device(int(q.device.index or 0))

    scalars = [
        ctypes.c_float(float(softmax_scale)),
        ctypes.c_float(float(k_scale)),
        ctypes.c_float(float(v_scale)),
    ]
    if variant.local:
        scalars.extend([
            ctypes.c_int32(int(window_size_left)),
            ctypes.c_int32(int(window_size_right)),
        ])

    scalar_count = sum(kind == "scalar" for kind in bundle.arg_kinds)
    if scalar_count != len(scalars):
        raise RuntimeError(
            f"forward scalar ABI mismatch for {variant.variant_key}: "
            f"artifact expects {scalar_count}, runtime provides {len(scalars)}"
        )
    stream = ctypes.c_void_p(get_raw_stream(int(q.device.index or 0)))

    def invoke(value: torch.Tensor, output: torch.Tensor) -> None:
        # Memref order matches the compile_fn's tensor order:
        #   dense: (Q, K, V, O); cu_seqlens_q: + mCuSeqlensQ;
        #   cu_seqlens_k: + mCuSeqlensK;
        #   seqused_q: + mSeqUsedQ;
        #   dense_seqused_k:     + mSeqUsedK;
        #   paged_kv_non_tma:    + mSeqUsedK, mPageTable;
        #   needs_aux_tensors:   + block_sequence_ids (trailing).
        tensors: list[torch.Tensor] = [q, k, value, output]
        if variant.cu_seqlens_q:
            assert cu_seqlens_q is not None
            tensors.append(cu_seqlens_q)
        if variant.cu_seqlens_k:
            assert cu_seqlens_k is not None
            tensors.append(cu_seqlens_k)
        if variant.seqused_q:
            assert seqused_q is not None
            tensors.append(seqused_q)
        if variant.dense_seqused_k:
            assert seqused_k is not None and page_table is None
            tensors.append(seqused_k)
        if variant.paged_kv_non_tma:
            assert seqused_k is not None and page_table is not None
            tensors.extend([seqused_k, page_table])
        if variant.needs_aux_tensors:
            assert aux_tensors, "block-bidirectional variant requires aux_tensors"
            tensors.append(aux_tensors[0])
        if len(bundle.memref_specs) != len(tensors):
            raise RuntimeError(
                f"memref count mismatch for {variant.variant_key}: "
                f"ciface expects {len(bundle.memref_specs)}, got {len(tensors)}"
            )
        bundle.invoke(
            [spec.build(tensor) for tensor, spec in zip(tensors, bundle.memref_specs)],
            scalars,
            stream,
        )

    if variant.kind == "forward_sm100" and variant.value_splits > 1:
        if v.shape[-1] != variant.head_dim or out.shape[-1] != variant.head_dim:
            raise ValueError(
                "value-split forward attention requires full-width V and output tensors"
            )
        value_width = variant.head_dim // variant.value_splits
        for split in range(variant.value_splits):
            start = split * value_width
            stop = start + value_width
            invoke(v[..., start:stop], out[..., start:stop])
    else:
        invoke(v, out)
    return True


# ---------------------------------------------------------------------------
# launch_decode_sm90 — FlashAttentionDecodeSm90 (all sm_8x/9x/10x/12x archs)
# ---------------------------------------------------------------------------

def launch_decode_sm90(
    variant: FlashAttnVariant,
    q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, out: torch.Tensor,
    softmax_scale: float, k_scale: float, v_scale: float,
    seqused_k: torch.Tensor, page_table: torch.Tensor,
    *,
    batch_size: int, num_heads_kv: int,
    window_size_left: int | None = None,
    window_size_right: int | None = None,
    require_packed: bool = False,
) -> bool:
    assert variant.kind == "decode_sm90"
    if not _ensure_available(variant.variant_key, q,
                             _compile_flash_attn_decode_sm90, variant, block_x=128,
                             require_packed=require_packed):
        return False
    resolve_dispatch = (
        _family.resolve_shipped_dispatch
        if require_packed else _family.resolve_dispatch
    )
    launcher = resolve_dispatch(
        q, variant_key=variant.variant_key,
        grid_x=batch_size, grid_y=num_heads_kv * _decode_group_count(variant),
    )
    args = (
        q, k, v, out, seqused_k, page_table,
        softmax_scale, k_scale, v_scale,
    )
    if variant.local:
        args += (window_size_left, window_size_right)
    launcher(*args)
    return True


# ---------------------------------------------------------------------------
# launch_sm80_forward — dense prefill on sm_80/86/87/89/120
# ---------------------------------------------------------------------------

def launch_sm80_forward(
    variant: FlashAttnSm80ForwardVariant,
    q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, out: torch.Tensor,
    softmax_scale: float, k_scale: float, v_scale: float,
    seqused_q: torch.Tensor | None = None,
    seqused_k: torch.Tensor | None = None,
    page_table: torch.Tensor | None = None,
    window_size_left: int | None = None,
    window_size_right: int | None = None,
    *,
    batch_size: int, seqlen_q: int, num_heads: int,
    aux_tensors: "list | None" = None,
    require_packed: bool = False,
) -> bool:
    if variant.needs_aux_tensors:
        # Aux-bearing variants (block_bidirectional) route through the AOT host
        # wrapper, which invokes the device kernel in its own compile-determined
        # param order — immune to that order, which the raw-cubin path
        # reconstructs from c_header and gets wrong (the kernel's internal param
        # ordering is PYTHONHASHSEED-dependent when an aux memref is present).
        # The wrapper derives the 3D grid from the q shape, so the grid args are
        # unused here. Non-aux variants keep the lower-overhead direct path.
        del batch_size, seqlen_q, num_heads
        resolver = (
            _aot_sm80_forward.resolve_shipped
            if require_packed else _aot_sm80_forward.resolve
        )
        bundle = resolver(variant, get_cuda_arch())
        if bundle is None:
            return False
        bundle.aot._ensure_device(int(q.device.index or 0))
        mem: list[torch.Tensor] = [q, k, v, out]
        if variant.paged_kv_non_tma:
            assert seqused_k is not None and page_table is not None
            if variant.seqused_q:
                assert seqused_q is not None
                mem.append(seqused_q)
            mem += [seqused_k, page_table]
        assert aux_tensors, "block-bidirectional sm80 variant requires aux_tensors"
        mem.append(aux_tensors[0])
        if len(bundle.memref_specs) != len(mem):
            raise RuntimeError(
                f"memref count mismatch for {variant.variant_key}: "
                f"ciface expects {len(bundle.memref_specs)}, got {len(mem)}"
            )
        structs = [s.build(t) for t, s in zip(mem, bundle.memref_specs)]
        scalars = [
            ctypes.c_float(float(softmax_scale)),
            ctypes.c_float(float(k_scale)),
            ctypes.c_float(float(v_scale)),
        ]
        stream = ctypes.c_void_p(get_raw_stream(int(q.device.index or 0)))
        bundle.invoke(structs, scalars, stream)
        return True

    # Non-aux variants: raw-cubin direct launch (CubinFamily), unchanged.
    if not _ensure_available(variant.variant_key, q,
                             _compile_flash_attn_sm80_forward, variant, block_x=128,
                             require_packed=require_packed):
        return False
    num_m_blocks = ceil_div(seqlen_q, variant.tile_m)
    resolve_dispatch = (
        _family.resolve_shipped_dispatch
        if require_packed else _family.resolve_dispatch
    )
    launcher = resolve_dispatch(
        q, variant_key=variant.variant_key,
        grid_x=num_m_blocks, grid_y=num_heads, grid_z=batch_size,
    )
    mem = [q, k, v, out]
    if variant.paged_kv_non_tma:
        assert seqused_k is not None and page_table is not None
        if variant.seqused_q:
            assert seqused_q is not None
            mem.append(seqused_q)
        mem += [seqused_k, page_table]
    args = [*mem, softmax_scale, k_scale, v_scale]
    if variant.local:
        args += [window_size_left, window_size_right]
    launcher(*args)
    return True


# ---------------------------------------------------------------------------
# launch_persistent_split_fused — CUDA-graph decode with split scheduler
# ---------------------------------------------------------------------------

def launch_persistent_split_fused(
    variant: FlashAttnDecodePersistentSplitFusedVariant,
    q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, out: torch.Tensor,
    softmax_scale: float, k_scale: float, v_scale: float,
    seqused_k: torch.Tensor, page_table: torch.Tensor,
    out_partial: torch.Tensor, lse_partial: torch.Tensor,
    split_counters: torch.Tensor,
    *,
    sm_count: int,
    require_packed: bool = False,
) -> bool:
    if not _ensure_available(variant.variant_key, q,
                             _compile_flash_attn_persistent_split_fused, variant,
                             block_x=128, require_packed=require_packed):
        return False
    resolve_dispatch = (
        _family.resolve_shipped_dispatch
        if require_packed else _family.resolve_dispatch
    )
    launcher = resolve_dispatch(
        q, variant_key=variant.variant_key,
        grid_x=int(sm_count), grid_y=1,
    )
    launcher(q, k, v, out, seqused_k, page_table,
             out_partial, lse_partial, split_counters,
             softmax_scale, k_scale, v_scale)
    return True


__all__ = [
    "launch_forward",
    "launch_decode_sm90",
    "launch_sm80_forward",
    "launch_persistent_split_fused",
]
